/* Create lead closing prices to compute forward Buy-and-hold returns subequent to ICO */
PROC EXPAND data=coinmarketcap2 out=coinmarketcap3 method=none;			
	convert close 		= close_lag1		/tout= (lag 1);
	convert close 		= close_lead1		/tout= (lead 1);
	convert close 		= close_lead90		/tout= (lead 90);	** 90 days / 3 mths;
	convert close 		= close_lead180		/tout= (lead 180);	** 180 days / 6 mths;
	by url;
	id date;
RUN;

/* Compute buy-and-hold ICO returns using price **/
* NOTE: We use "ret1d" to indicate past return, and "ret_1d" (with underscore) to indicate forward return;
* NOTE: We require a minimum price of $0.001 to reduce the impact of outliers;
* NOTE: Generally, _1d _3m and so on indicate forward looking measures;
* NOTE: The returns with 'p' at the end are calculated using price data, i.e. BHAR;
DATA coinmarketcap4; 
SET coinmarketcap3;
	year = year(date);
	month_index = (year(date) - 1955) * 12 + month(date);
	qtr_index 	= (year(date) - 1955) * 4 + qtr(date);
	if close>0.001 then; ret_1d 	= (close_lead1	/close)-1;
	if close>0.001 then; lnret_1d 	= log(close_lead1	/close);
	if close>0.001 then; ret_3mp 	= (close_lead90	/close)-1;
	if close>0.001 then; ret_6mp 	= (close_lead180/close)-1;
	if close_lag1>0.001 then; ret1d		= (close/close_lag1)-1;
	if close_lag1>0.001 then; lnret1d 	= log(close/close_lag1);
	if abs(ret1d)>0 and volume>100 then amihud1d = abs(ret1d)/volume*1000;
	ln_liq1d = -1*log(1+(abs(ret1d)/volume));

*** 7. Append relevant variables re. Unrated ICOs (third data collection)    ***;
********************************************************************************;
* NOTE: We manually append data on unrated ICOs collected in Nov 2019 with "icodata" from step 6 above;
* NOTE: We hand-checked for duplicates and created indicator to drop these (See step 7.1 below);
* NOTE: We also corrected the combined_name for three ICOs (See step 7.0 below);
* NOTE: The cleaned dataset "icodata_merged_corrected" is read into SAS to create final dataset for analysis;

DATA icodata_all;
SET icodata_merged_corrected;
*3,387 ICOs read in;

/* 15. Update page count for unrated WPs */
PROC SQL;
	create table icodata_all2 as
	select a.*, b.pages
	from  icodata_all as a
	LEFT JOIN ico.unrated_page_count_data as b
on a.nc_whitepaper_pdf_filename = b.nc_whiteper_pdf_filename; 
QUIT; RUN;
DATA  icodata_all2;
SET icodata_all2;
	wp_page_count  = coalesce(pages, WPC_page_count); 
RUN;

/* 16. Add in website data for both rated and unrated ICOs */
PROC SQL;
	create table icodata_all3 as
	select a.*, b.active as website_active 
	from  icodata_all2 as a
	LEFT JOIN ico.websites as b
	on a.combined_name = b.combined_name; 
QUIT; RUN;

DATA icodata_all3;
SET icodata_all3;
	if nc_website_inactive = 0 then nc_active = 1; else nc_active = 0; 
	if nc_website_inactive = . then nc_active = .;
	active_website_ind = coalesce(NC_active, website_active); 
	DROP nc_active nc_website_inactive website_active; 
RUN; * NOTE: active_website_ind is the same as "active_website_ind2" in final STATA dataset;

/* 17. Add in FOG for unrated WPs and coalesce with old data */
PROC SQL;
	create table icodata_all4 as
	select a.*, b.fogscore as nc_fog, b.wordcount as nc_wordcount  
	from  icodata_all3 as a
	LEFT JOIN ico.unrated_fog as b
	on a.nc_whitepaper_pdf_filename = b.pdf_name;

/* Final data clean: Fix 3 data errors (from rawdata files) and save output file for STATA analysis */
