/* Read in coinmarketcap ("CMC") daily market data */
PROC SORT data=rawdata.coinmarketcap out=coinmarketcap0 NODUPKEY DUPOUT=dups; 
	BY url date; RUN;
** 1,366,622 obs;

/* Merge CMC daily market data to tokens in our "Names" linking table (i.e. keep checked tokens only) */
DATA cmc_names; 
SET rawdata.names;
	where not missing(url_cmc);
RUN; 
** 1,328 tokens with cmc name in "Names" file (no duplicates);
PROC SQL;
	create table coinmarketcap00 
	as select a.*, b.url_cmc
	from 	coinmarketcap0 as a, 
			cmc_names as b 
	where a.url=b.url_cmc
	order by a.url, a.date;

/* Read in and clean "Names" file - which will form the basis of our cross-sectional dataset **/ 
DATA names; 
SET rawdata.names; 
	where combined_drop=0; 
	DROP secid icoid;
RUN;
** 3,387 ICOs; 

*check to ensure no dups by combined_name (combined_name becomes the new unique identifier);
PROC SORT data=names out=names1 nodupkey dupout=dups; 
	BY combined_name; RUN;

/* Merge in CMC daily market data to the cleaned ICO-level "Names" file **/ 
PROC SQL;
	create table coinmarketcap7 as select 	 
	a.combined_name, b.*,
	a.name_icobench, a.old_name_icobench, a.new_name_icobench,
	a.name_coinschedule, a.name_tokendata, a.name_icorating, a.name_smith_crown,
	a.combined_name_old, a.in_old_sample, a.end_date_combined, a.whitepaper_old, a.whitepaper_new
 	from names1 as a
	LEFT JOIN coinmarketcap6 as b	 
	on a.url_cmc=b.url
	order by a.combined_name, b.date;

