/* Prepare BTC and ETH currency return files and aggregate over time */ 
PROC SQL;
	create table exchange_ret as select a.date,
	a.eth as eth_ret1d, a.btc as btc_ret1d,
	b.eth as eth_ret_1d, b.btc as btc_ret_1d
	from rawdata.exchange_ret as a 
	LEFT JOIN rawdata.exchange_ret as b on a.date+1=b.date and not missing(b.date)
order by a.date;
QUIT;
* 1,786 obs;

/* Aggregate daily exchange rate returns over time (6m) **/
PROC EXPAND data=exchange_ret out=exchange_ret1 method=none;
	convert eth_ret_1d			= eth_ret_6m 		/ tin=(+1 log) tout=(reverse nomiss movsum 180 exp -1 reverse trimright 179);
	convert btc_ret_1d			= btc_ret_6m 		/ tin=(+1 log) tout=(reverse nomiss movsum 180 exp -1 reverse trimright 179);
	id date;
RUN;
* 1,786 obs;

/* Create (past) BTC momentum (3m) **/
PROC EXPAND data=exchange_ret1 out=exchange_ret2 method=none;
	convert btc_ret1d			= btc_mom_3m 		/ tin=(+1 log) tout=(nomiss movsum 90 exp -1 trimleft 89);
	id date;
RUN;
* 1,786 obs;

/* Merge in ETH and BTC momentum variables **/
PROC SQL;
	create table coinmarketcap17 as select a.*,
	b.eth as eth_usd_icoend, b.btc as btc_usd_icoend,
	c.eth as eth_usd, c.btc as btc_usd,
	d.eth_ret1d, d.eth_ret_1d, d.eth_ret_6m, d.btc_ret1d, d.btc_ret_1d, d.btc_ret_6m, d.btc_mom_3m
	from coinmarketcap16 as a 
	LEFT JOIN  rawdata.exchange_level as b on a.icoenddate=b.date and not missing(a.end_icobench)
	LEFT JOIN rawdata.exchange_level as c on a.date=c.date and not missing(a.end_icobench)
	LEFT JOIN exchange_ret2 as d on a.date=d.date and not missing(d.date);
QUIT;

